@test
def test_misc():
    assert close(FlatChannelRemover().fit_transform(X), E_flat, atol=1e-08)
    assert close(ElectrodeSelection(2).fit(cov, y).subelec_, E_es_sub, atol=1e-08)
    assert close(ElectrodeSelection(2).fit_transform(cov, y), E_es_t, atol=1e-08)
    assert close(Whitening("riemann").fit_transform(cov), E_wh, atol=1e-08)
    assert close(Whitening("euclid", "n_components", 2.0).fit_transform(cov), E_wh_nc, atol=1e-08)
    assert close(Whitening("euclid", "expl_var", 0.9).fit_transform(cov), E_wh_ev, atol=1e-08)
    assert close(inv_roundtrip(cov), E_wh_inv, atol=1e-08)
    assert close(median_euclid(cov), E_med_e, atol=1e-07)
    assert close(median_riemann(cov), E_med_r, atol=1e-07)
    assert close(TLCenter("tgt").fit_transform(Xe, ye), E_tlc, atol=1e-08)
    assert close(TLCenter("tgt").fit(Xe, ye).transform(cov), E_tlc_t, atol=1e-08)
    assert close(TLScale("tgt", 2.0).fit_transform(Xe, ye), E_tls, atol=1e-07)
    assert close(TLScale("tgt").fit(Xe, ye).transform(cov), E_tls_t, atol=1e-07)
    assert close(Kmeans(3, 100, "riemann", 3).fit(cov).labels_, E_km_lab, atol=1e-08)
    assert close(Kmeans(3, 100, "riemann", 3).fit(cov).centroids(), E_km_cent, atol=1e-07)
    Pm = np.array([[2.0, 1.0], [1.0, 3.0]])
    assert [is_sym(Pm), is_pos_def(Pm), is_hankel(np.array([[1.0, 2.0], [2.0, 3.0]])), is_skew_sym(Pm), is_pos_semi_def(np.array([[1.0, 1.0], [1.0, 1.0]])), is_sym_pos_def(np.array([[1.0, 2.0], [2.0, 1.0]]))] == [True, True, True, False, True, False]
test_misc()
